export default function makeCard(ship) {
  const card = document.createElement("li");
  card.className = "ship";
  card.innerHTML = '<h2 class="ship-name"></h2>';
  card.querySelector(".ship-name").textContent = "Made by the test: " + ship.name;
  return card;
}

